import React, { useState } from 'react';
import { Link, useNavigate } from 'react-router-dom';
import { Home, Eye, EyeOff } from 'lucide-react';
import { useAuth } from '../context/AuthContext';
import './Auth.css';

export default function Register() {
  const { login } = useAuth();
  const navigate = useNavigate();
  const [form, setForm] = useState({ name: '', email: '', phone: '', role: 'client', agency: '', password: '', confirm: '' });
  const [showPw, setShowPw] = useState(false);
  const [error, setError] = useState('');

  const set = (k, v) => setForm(f => ({ ...f, [k]: v }));

  const handleSubmit = (e) => {
    e.preventDefault();
    if (form.password !== form.confirm) { setError('Passwords do not match.'); return; }
    if (form.password.length < 6) { setError('Password must be at least 6 characters.'); return; }
    const user = { name: form.name, email: form.email, phone: form.phone, role: form.role, agency: form.agency };
    login(user);
    navigate(form.role === 'agent' ? '/agent' : '/client');
  };

  return (
    <div className="auth-page">
      <div className="auth-card auth-card-wide">
        <div className="auth-brand">
          <Home size={28} />
          <span>Prop<strong>Connect</strong></span>
        </div>
        <h1>Create an account</h1>
        <p className="auth-sub">Join PropConnect as a client or property agent</p>

        {error && <div className="alert alert-error">{error}</div>}

        <div className="role-selector">
          {['client', 'agent'].map(r => (
            <button
              key={r}
              type="button"
              className={`role-option ${form.role === r ? 'active' : ''}`}
              onClick={() => set('role', r)}
            >
              <strong style={{ textTransform: 'capitalize' }}>{r}</strong>
              <span>{r === 'client' ? 'Browse & request viewings' : 'List & manage properties'}</span>
            </button>
          ))}
        </div>

        <form onSubmit={handleSubmit}>
          <div className="form-row-2">
            <div className="form-group">
              <label>Full Name</label>
              <input className="form-control" required value={form.name} onChange={e => set('name', e.target.value)} placeholder="Your full name" />
            </div>
            <div className="form-group">
              <label>Phone Number</label>
              <input className="form-control" required value={form.phone} onChange={e => set('phone', e.target.value)} placeholder="07x xxx xxxx" />
            </div>
          </div>
          <div className="form-group">
            <label>Email Address</label>
            <input className="form-control" type="email" required value={form.email} onChange={e => set('email', e.target.value)} placeholder="your@email.com" />
          </div>
          {form.role === 'agent' && (
            <div className="form-group">
              <label>Agency Name</label>
              <input className="form-control" required value={form.agency} onChange={e => set('agency', e.target.value)} placeholder="Your agency or company name" />
            </div>
          )}
          <div className="form-row-2">
            <div className="form-group">
              <label>Password</label>
              <div className="pw-wrap">
                <input className="form-control" type={showPw ? 'text' : 'password'} required value={form.password} onChange={e => set('password', e.target.value)} placeholder="Min. 6 characters" />
                <button type="button" className="pw-toggle" onClick={() => setShowPw(!showPw)}>
                  {showPw ? <EyeOff size={16} /> : <Eye size={16} />}
                </button>
              </div>
            </div>
            <div className="form-group">
              <label>Confirm Password</label>
              <input className="form-control" type="password" required value={form.confirm} onChange={e => set('confirm', e.target.value)} placeholder="Repeat password" />
            </div>
          </div>
          <button type="submit" className="btn btn-primary auth-submit">Create Account</button>
        </form>

        <p className="auth-footer">Already have an account? <Link to="/login">Sign in</Link></p>
      </div>
    </div>
  );
}
